<script setup lang="ts">import { onMounted, ref } from 'vue'; import axios from 'axios'; import api from '../plugins/axios'; const items=ref<any[]>([]); const error=ref(''); async function cargar(){try{items.value=(await api.get('/reembolsos')).data}catch(e){error.value=axios.isAxiosError(e)?e.response?.data?.message??'No se pudieron cargar los reembolsos.':'No se pudieron cargar los reembolsos.'}} async function realizar(id:number){try{await api.post(`/reembolsos/${id}/realizar`);await cargar()}catch(e){error.value=axios.isAxiosError(e)?e.response?.data?.message??'No se pudo realizar el reembolso.':'No se pudo realizar el reembolso.'}} onMounted(cargar)</script>
<template><section class="container py-5"><h1 class="h2 fw-bold mb-4">Reembolsos</h1><div v-if="error" class="alert alert-danger">{{ error }}</div><div class="table-responsive"><table class="table"><thead><tr><th>Pedido</th><th>Cliente</th><th>Monto</th><th>Estado</th><th></th></tr></thead><tbody><tr v-for="item in items" :key="item.idReembolso"><td>#{{ item.pedido?.idPedido }}</td><td>{{ item.pedido?.cliente?.nombreCompleto || item.pedido?.cliente?.celular }}</td><td>{{ Number(item.monto).toFixed(2) }} Bs</td><td>{{ item.estado }}</td><td><button v-if="item.estado === 'solicitado'" class="btn btn-sm btn-primary" type="button" @click="realizar(item.idReembolso)">Marcar realizado</button></td></tr></tbody></table></div></section></template>
